const MW_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${MW_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.op?` fill-opacity="${o.op}"`:''}>${t}</text>`;
const MW_L=(x1,y1,x2,y2,col=MW_G,w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const MW_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.dash?` stroke-dasharray="${o.dash}"`:''}${o.op?` fill-opacity="${o.op}"`:''}/>`;
const MW_ar=(x1,y1,x2,y2,col='#18213A',w=4,dash='')=>{const a=Math.atan2(y2-y1,x2-x1),h=16;return MW_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w,dash?`stroke-dasharray="${dash}"`:'')+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const MW_X=(x,y,s,col)=>MW_L(x-s,y-s,x+s,y+s,col,6)+MW_L(x-s,y+s,x+s,y-s,col,6);
const MW_pl=(pts,col,w=4,ex='')=>`<polyline points="${pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
/* sample a function into points: x from x0 to x1 (pixels), t from t0 to t1, y = f(t) already in pixels */
const MW_fn=(f,t0,t1,x0,x1,n=120)=>{const p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push([x0+(x1-x0)*i/n,f(t)])}return p};
/* a horn seen from the side, mouth to the right (dir 1) or left (dir -1) */
const MW_horn=(x,y,dir,col,s=1)=>`<polygon points="${x},${y-12*s} ${x+dir*44*s},${y-34*s} ${x+dir*44*s},${y+34*s} ${x},${y+12*s}" fill="#FFFFFF" stroke="${col}" stroke-width="3" stroke-linejoin="round"/>`;
/* a resonance curve, normalised power 1/(1 + (2Q(f/f0 − 1))²), plotted over f = fa..fb */
const MW_res=(Q,f0,fa,fb,x0,x1,ybase,hgt)=>MW_fn(f=>ybase-hgt/(1+Math.pow(2*Q*(f/f0-1),2)),fa,fb,x0,x1,160);
/* the far-field pattern of a uniform aperture two wavelengths wide, in dB (floored at −30) */
const MW_patdB=th=>{const u=2*Math.PI*Math.sin(th);const F=Math.abs(u)<1e-9?1:Math.sin(u)/u;return Math.max(-30,20*Math.log10(Math.abs(F)+1e-12))};
/* the earth and the ionosphere as arcs about one centre */
const MW_eY=x=>1300-Math.sqrt(900*900-(x-320)*(x-320)), MW_iY=x=>1300-Math.sqrt(1180*1180-(x-320)*(x-320));

